    description: "详细讲解小升初简历的写作方法，包含真实模板示例和每个模块的填写技巧，帮助家长制作一份有竞争力的简历。涵盖成绩展示、荣誉奖项、自荐信、特长展示和教师推荐等核心模块，每个模块附优秀范例和避坑指南。附可打印简历模板和免费在线工具推荐，适合五年级和六年级家庭提前准备，助力孩子顺利升入理想初中，操作简单适合长期使用。",
