数独是一款零门槛、高上限的思维训练游戏。它不需要任何前置知识，却能持续挑战孩子的思维极限。

最重要的是，数独让孩子体验到思考的乐趣。当他独立解出一道难题时，那种成就感是任何奖励都无法替代的。

如果你还没让孩子尝试过数独，不妨从今天开始。记住三个要点：
