  "title": "暑假两个月，孩子不想学习只抱着手机？我用这套「30分钟计划」让儿子从抗拒到主动做题",
  "description": "暑假孩子沉迷手机、不想学习怎么办？本文分享一套经过验证的30分钟微学习计划，让孩子在暑假中保持学习状态，每天只需30分钟，从抗拒到主动。",
